import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import test from 'node:test';
import { distDir, distExists, decode, listHtmlFiles } from './support/dist.mjs';
import { pageOg, slugFor } from '../src/data/og.ts';
import { scenes, ogSceneFor } from '../src/data/scenes.mjs';

// Share cards are generated by the build from src/data/og.ts, in the Ouro
// brand: nobody draws or uploads them by hand (Ari, 2026-10-15). Since the
// storybook world (2026-11-06) each one sets its title over its page's scene.

const meta = (html, attr, name) => {
  const m = html.match(new RegExp(`<meta ${attr}="${name}" content="([^"]*)"`));
  return m ? decode(m[1]) : undefined;
};

test('every share card names a mark that exists', () => {
  for (const [route, entry] of Object.entries(pageOg)) {
    const mark = entry.mark ?? 'ouro';
    assert.ok(fs.existsSync(path.join('src/og/marks', `${mark}.png`)), `${route}: missing mark ${mark}`);
  }
});

// The width and height from a JPEG's start-of-frame marker.
const jpegSize = (bytes) => {
  for (let i = 2; i < bytes.length;) {
    const marker = bytes[i + 1];
    if (marker >= 0xc0 && marker <= 0xc3) return [bytes.readUInt16BE(i + 7), bytes.readUInt16BE(i + 5)];
    i += 2 + bytes.readUInt16BE(i + 2);
  }
  return null;
};

test('every share card is set in a storybook scene the site serves', () => {
  for (const route of Object.keys(pageOg)) {
    const scene = ogSceneFor(route);
    assert.ok(scene in scenes, `${route}: unknown scene ${scene}`);
    assert.ok(distExists(`brand/storybook/og/${scene}.jpg`), `${route}: og scene ${scene} is not served`);
  }
});

test('the build generates a 1200x630 JPEG card for every manifest entry, small enough for any feed', () => {
  for (const route of Object.keys(pageOg)) {
    const file = `og/${slugFor(route)}.jpg`;
    assert.ok(distExists(file), `${route}: ${file} was not generated`);
    const jpg = fs.readFileSync(path.join(distDir, file));
    assert.equal(jpg.readUInt16BE(0), 0xffd8, `${file} is a JPEG`);
    assert.deepEqual(jpegSize(jpg), [1200, 630], `${file} size`);
    assert.ok(jpg.length < 400_000, `${file} is ${jpg.length} bytes`);
  }
});

test('every page advertises an existing card with its size and alt text', () => {
  for (const file of listHtmlFiles()) {
    const html = fs.readFileSync(file, 'utf8');
    const image = meta(html, 'property', 'og:image');
    if (!image) continue;
    const page = path.relative(distDir, file);
    assert.ok(distExists(new URL(image).pathname), `${page}: ${image} is not in the build`);
    assert.equal(meta(html, 'name', 'twitter:image'), image, `${page}: twitter:image`);
    assert.equal(meta(html, 'property', 'og:image:width'), '1200', `${page}: og:image:width`);
    assert.equal(meta(html, 'property', 'og:image:height'), '630', `${page}: og:image:height`);
    const alt = meta(html, 'property', 'og:image:alt');
    assert.ok(alt && alt.length > 10, `${page}: og:image:alt`);
    assert.equal(meta(html, 'name', 'twitter:image:alt'), alt, `${page}: twitter:image:alt`);
    assert.equal(meta(html, 'property', 'og:site_name'), 'Ouro', `${page}: og:site_name`);
  }
});

test('the homepage card says what the card shows', () => {
  const html = fs.readFileSync(path.join(distDir, 'index.html'), 'utf8');
  const entry = pageOg['/'];
  assert.equal(meta(html, 'property', 'og:image:alt'), `${entry.title} ${scenes.ourostack}`);
});

// One type scale on every card (taste review r5, 2026-11-06): the title is set
// at a single size and only its line count changes, and a zone too small for it
// fails the build instead of shrinking the words.
test('every share card sets its title at the one title size', () => {
  const src = fs.readFileSync('src/pages/og/[...slug].jpg.ts', 'utf8');
  assert.match(src, /export const TITLE_SIZE = \d+/);
  assert.match(src, /const titleSize = TITLE_SIZE\n/);
  assert.match(src, /if \(!lines\) throw new Error/);
});

// Taste review r12 (second time flagged): the Butler card's title sat on a
// hard-edged light band that bleached the cottage roof. Ruling: no band. The
// title stands in the scene's own sky, the roof clears it, and the sky meets
// the scene without a line. These hold the measurable half; the look is checked
// by eye next to three other cards.
test('the Butler card sets its title in open sky, with no band over the roof', async () => {
  const { default: sharp } = await import('sharp');
  const file = path.join(distDir, 'og/og-butler.jpg');
  assert.ok(fs.existsSync(file), 'og-butler.jpg was not built');
  const { data, info } = await sharp(file).removeAlpha().raw().toBuffer({ resolveWithObject: true });
  assert.deepEqual([info.width, info.height], [1200, 630]);
  const lin = (v) => { v /= 255; return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4; };
  const lum = (i) => 0.2126 * lin(data[i]) + 0.7152 * lin(data[i + 1]) + 0.0722 * lin(data[i + 2]);
  const ink = 0.2126 * lin(0x1a) + 0.7152 * lin(0x21) + 0.0722 * lin(0x18);
  // AA behind the title: the sky's median in every 100px strip of the title rows.
  for (let x0 = 16; x0 < 1100; x0 += 100) {
    const ls = [];
    for (let y = 16; y < 130; y++) for (let x = x0; x < x0 + 100; x++) ls.push(lum((y * info.width + x) * 3));
    ls.sort((a, b) => a - b);
    const ratio = (ls[ls.length >> 1] + 0.05) / (ink + 0.05);
    assert.ok(ratio >= 4.5, `the sky behind the title at x=${x0} gives ${ratio.toFixed(2)}:1, under AA`);
  }
  // No line where the sky meets the scene: across the roof's columns, no
  // four-row step in brightness between the title and the roof (the old band's
  // edge stepped 22 levels at y=193).
  const rows = [];
  for (let y = 0; y < 240; y++) {
    let s = 0;
    for (let x = 200; x < 680; x++) s += lum((y * info.width + x) * 3) ** (1 / 2.2) * 255;
    rows.push(s / 480);
  }
  for (let y = 140; y < 230; y++) {
    const step = Math.abs(rows[y + 2] - rows[y - 2]);
    assert.ok(step < 16, `a ${step.toFixed(1)}-level edge at y=${y} over the cottage roof`);
  }
});
